class ReportBuilder:
    """Collects the lines of a plain-text report as a job produces them, then returns the finished text."""

    def __init__(self, title):
        self.text = title + "\n"

    def add_line(self, line):
        """Append one line (given without its newline)."""
        self.text += line + "\n"

    def build(self):
        """Return the report: the title line, then every added line in order, each followed by a newline."""
        return self.text

