class Work:
    """How many characters the code under test has copied by concatenating or formatting, and the most it may copy (None: no limit)."""
    copied = 0
    size = 0
    limit = None

    @classmethod
    def add(cls, n):
        cls.copied += n
        if cls.limit is not None and cls.copied > cls.limit:
            raise AssertionError(f"copied {cls.copied:,} characters and still going, for a report of only {cls.size:,}: every line added makes the code copy the whole report so far, so the work grows with the square of the number of lines")
class Text(str):
    """A piece of text that counts the characters copied whenever it is added to another string or formatted into one."""
    def __add__(self, other):
        Work.add(len(self) + len(other))
        return Text(str.__add__(self, other))

    def __radd__(self, other):
        Work.add(len(self) + len(other))
        return Text(str.__add__(other, self))

    def __format__(self, spec):
        Work.add(len(self))
        return str.__format__(self, spec)
def stored_strings(obj):
    """(name, value) for every str the object keeps in its attributes (instance dict and slots)."""
    found = list(getattr(obj, "__dict__", {}).items())
    found += [(name, getattr(obj, name)) for name in getattr(type(obj), "__slots__", ()) if hasattr(obj, name)]
    return [(name, value) for name, value in found if isinstance(value, str)]
def build_big_report(n_lines, width):
    """Add many lines with the copying metered (title and lines are Text), and check the finished report."""
    title = "Daily export"
    lines = [f"row {i:06d} " + "x" * width for i in range(n_lines)]
    expected = title + "\n" + "".join(line + "\n" for line in lines)
    Work.copied, Work.size, Work.limit = 0, len(expected), 20 * len(expected)
    try:
